  }

  override pay(): number {
    const regular = Math.min(this.hours, 40);
    const overtime = this.hours - regular;
    return this.rate * regular + this.rate * 1.5 * overtime;
  }
}

class CommissionedEmployee extends Employee {
  private readonly base: number;
  private readonly sales: number;

  constructor(base: number, sales: number) {
    super("commissioned");
    this.base = base;
    this.sales = sales;
  }

  override pay(): number {
    return this.base + this.sales * 0.1;
  }
}

function totalPay(employees: Employee[], kind: string): number {
  let total = 0;
  for (const employee of employees) {
    if (employee.kind === kind) {
      total += employee.pay();
    }
  }
  return total;
}

